  const handleAiPlan = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    try {
      const result = await generateItinerary(aiPrompt, {
        persona: profile.persona,
        interests: profile.interests,
        budget: profile.budget
      });
      setItinerary(result);
