import React, { useState } from 'react';
import { PERSONAS, VIBES, MOCK_EXPERIENCES, LanternIcon } from './constants';
import { UserProfile, ItineraryResponse } from './types';
import Navigation from './components/Navigation';
import { generateItinerary } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('discover');
  const [profile, setProfile] = useState<UserProfile>({
    name: '',
    persona: 'traveler',
    interests: [],
    budget: 'medium',
    isOpenToMeet: false,
    onboarded: false
  });

  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [itinerary, setItinerary] = useState<ItineraryResponse | null>(null);

  const handleOnboarding = (e: React.FormEvent) => {
    e.preventDefault();
    if (profile.name && profile.interests.length > 0) {
      setProfile(prev => ({ ...prev, onboarded: true }));
    }
  };

  const toggleInterest = (interest: string) => {
    setProfile(prev => {
      const interests = prev.interests.includes(interest)
        ? prev.interests.filter(i => i !== interest)
        : [...prev.interests, interest];
      return { ...prev, interests };
    });
  };

  const handleAiPlan = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    try {
      const result = await generateItinerary(aiPrompt, {
        persona: profile.persona,
        interests: profile.interests,
        budget: profile.budget
      });
      setItinerary(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  // --- VIEWS ---

  const OnboardingView = () => (
    <div className="min-h-screen bg-white p-10 flex flex-col justify-between animate-fade-in overflow-hidden relative">
