                 <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Duration • {exp.duration}</p>
                 <p className="text-[10px] font-black uppercase tracking-widest text-[#de2810]">Price • {exp.cost}</p>
               </div>
